examples.code:
// Add the squad, then place the first players on specific positions.
// Each call swaps the player with the one already on that position.
CMND_BTL_ADD_MEMBER(0, "para_cp0001", 1, 1);
CMND_BTL_ADD_MEMBER(0, "para_cp0002", 1, 2);
CMND_BTL_ADD_MEMBER(0, "para_cp0003", 1, 3);
CMND_BTL_ADD_MEMBER(0, "para_cp0004", 1, 4);
CMND_BTL_CHANGR_MEMBER_POS(0, "para_cp0001", 1);
CMND_BTL_CHANGR_MEMBER_POS(0, "para_cp0003", 2);
CMND_BTL_CHANGR_MEMBER_POS(0, "para_cp0004", 3);
CMND_BTL_CHANGR_MEMBER_POS(0, "para_cp0002", 4);

// para_cp0005 was not added by the script: it comes from the player's
// team, and is moved to position 4 of the 5-a-side line-up.
CMND_BTL_CHANGR_MEMBER_POS(0, "para_cp0005", 4);
